import XCTest
import AVFoundation
@testable import HandyTools

/// Matroska and WebM: an H.264 + AAC .mkv becomes a real MP4 with both tracks and the right length; VP9 + Opus
/// (as .webm or .mkv) is handed to the web player, with an .mkv's label changed to "webm". Clips made with ffmpeg.
final class MatroskaTests: XCTestCase {
    private func file(_ b64: String, _ name: String) throws -> URL {
        let d = try XCTUnwrap(Data(base64Encoded: b64, options: .ignoreUnknownCharacters))
        let u = FileManager.default.temporaryDirectory.appendingPathComponent(name)
        try d.write(to: u)
        return u
    }

    func testReadsTracksAndFrames() throws {
        let d = try XCTUnwrap(Data(base64Encoded: Self.h264AAC, options: .ignoreUnknownCharacters))
        let m = try XCTUnwrap(Matroska.parse(d))
        XCTAssertEqual(m.docType, "matroska")
        XCTAssertEqual(m.tracks.map(\.codec), ["V_MPEG4/ISO/AVC", "A_AAC"])
        XCTAssertEqual(m.tracks[0].width, 160); XCTAssertEqual(m.tracks[0].height, 120)
        XCTAssertEqual(m.frames.filter { $0.track == 1 }.count, 15)
        XCTAssertEqual(m.frames.filter { $0.track == 1 && $0.key }.count, 1)
        XCTAssertEqual(m.frames.filter { $0.track == 2 }.count, 45)
        // B-frames: stored in decode order, so show times go back and forth.
        let shows = m.frames.filter { $0.track == 1 }.map(\.ns)
        XCTAssertNotEqual(shows, shows.sorted())
    }

    func testH264MKVBecomesPlayableMP4() async throws {
        let src = try file(Self.h264AAC, "clip.mkv")
        guard case .mp4(let out, let dropped) = Matroska.open(src) else { return XCTFail("expected an MP4") }
        XCTAssertFalse(dropped)
        let asset = AVURLAsset(url: out)
        let v = try await asset.loadTracks(withMediaType: .video), a = try await asset.loadTracks(withMediaType: .audio)
        XCTAssertEqual(v.count, 1); XCTAssertEqual(a.count, 1)
        let seconds = try await asset.load(.duration).seconds
        XCTAssertEqual(seconds, 1, accuracy: 0.2)
        let playable = try await asset.load(.isPlayable)
        XCTAssertTrue(playable)
        // The first picture decodes.
        let gen = AVAssetImageGenerator(asset: asset)
        let (img, _) = try await gen.image(at: .zero)
        XCTAssertEqual(img.width, 160)
        if case .quickLook = FileReaders.read(src) {} else { XCTFail("File Opener should show the MP4") }
    }

    func testWebMGoesToWebPlayer() throws {
        let src = try file(Self.vp9Opus, "clip.webm")
        guard case .web(let out) = Matroska.open(src) else { return XCTFail("expected the web player") }
        XCTAssertEqual(out.pathExtension, "webm")
        if case .webVideo = FileReaders.read(src) {} else { XCTFail("File Opener should use the web player") }
    }

    func testVP9MKVIsRelabelledWebM() throws {
        let src = try file(Self.vp9OpusMKV, "clip-vp9.mkv")
        XCTAssertEqual(Matroska.parse(try Data(contentsOf: src))?.docType, "matroska")
        guard case .web(let out) = Matroska.open(src) else { return XCTFail("expected the web player") }
        let copy = try XCTUnwrap(Matroska.parse(try Data(contentsOf: out)))
        XCTAssertEqual(copy.docType, "webm")
        XCTAssertEqual(copy.frames.count, Matroska.parse(try Data(contentsOf: src))?.frames.count)
    }

    func testDamagedFileExplainsItself() throws {
        let d = try XCTUnwrap(Data(base64Encoded: Self.h264AAC, options: .ignoreUnknownCharacters))
        let u = FileManager.default.temporaryDirectory.appendingPathComponent("cut.mkv")
        try d.prefix(40).write(to: u)
        if case .problem = Matroska.open(u) {} else { XCTFail("a cut-off file should say so") }
    }

    func testSupportTableAgrees() {
        for e in ["mkv", "mka", "webm", "msg", "rar", "7z", "bz2", "mid", "ogg"] {
            XCTAssertEqual(FileReaders.support(e), .reads, e)
        }
    }

    func testEsdsWrapsConfig() {
        let e = Matroska.esds(Data([0x12, 0x10]))
        XCTAssertEqual(e.first, 0x03)
        XCTAssertEqual(Array(e.suffix(8)), [0x12, 0x10, 0x06, 0x80, 0x80, 0x80, 0x01, 0x02])
    }

